INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 13, 'theory', 'Quiz: HTML — Document, Semantics and Accessibility');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 13, 0, 'What is the lang attribute on the html element for?', '["It sets the file encoding", "It changes the page font", "It tells translators, search engines and speech software which language the page is in", "It turns on compatibility mode for old browsers"]', 2, 'lang does not affect appearance: it helps a screen reader pick the pronunciation, helps with hyphenation rules and gives a hint to translators. The encoding is set by the charset meta tag, and the parsing mode by the doctype.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 13, 1, 'Which sequence of headings is correct?', '["One h1, then h2, and an h3 inside an h2", "Several h1 in a row, because h1 is bigger", "First h1, then straight h4, to get a smaller font", "Only h3: it has a convenient size"]', 0, 'Headings are an outline: one h1, and the levels go in order with no gaps. Font size is set with styles, and the level is chosen by the place in the structure.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 13, 2, 'Why do you add rel with noopener and noreferrer to a link with target="_blank"?', '["So the link opens faster", "So search engines do not index the page", "So the link turns into an anchor", "So the opened page cannot access yours and does not learn the address of the source"]', 3, 'Without it, the page in the new tab could control the source window through window.opener. Modern browsers already imply noopener, but it is still worth writing it out.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 13, 3, 'Which element fits the main content of a page?', '["a div with the class content", "main: there is one per page and it gives a screen reader a landmark", "section: there are several, so one of them is the main one", "aside: it is always in the middle"]', 1, 'main marks the primary content and also serves as a landmark for a screen reader; there is one per page. A div tells nothing, and aside is secondary content.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 13, 4, 'What will the browser do if a paragraph is not closed and a new block starts after it?', '["Show an error message and stop loading", "Not display the page at all", "Close the paragraph itself and build the tree by the parsing rules of the standard", "Make all the remaining text part of the paragraph in a small font"]', 2, 'HTML parsing is specified in detail and forgives errors: missing tags are added, stray ones are moved. But the tree may end up different from what you intended, which is why markup is checked with a validator.');
